<script setup lang="ts">
import { computed, watch } from 'vue';
import { useRouter } from 'vue-router';
import { ArrowRight, Collection, EditPen, CircleCheck, Clock, Connection, Search, DataAnalysis } from '@element-plus/icons-vue';
import { ElMessage } from 'element-plus';
import { useWorkbenchStore } from '../stores/workbench';
import { groupMeta, toolTitle } from '../data/presentation';
const store = useWorkbenchStore();
const router = useRouter();
const groups = computed(() => {
  const counts: Record<string, number> = {};
  store.tools.forEach(tool => { counts[tool.group] = (counts[tool.group] ?? 0) + 1; });
  return Object.entries(counts).map(([id, count]) => ({ id, count, ...(groupMeta[id] ?? { label: id, description: '', color: '#6366f1' }) }));
});
const readCount = computed(() => store.tools.filter(tool => !tool.isWrite).length);
const pending = computed(() => store.drafts.filter(draft => draft.status === 'pending').length);
const recent = computed(() => store.history.slice(0, 5));
const statusText: Record<string, string> = { success: '成功', held: '待审批', error: '失败', running: '运行中', cancelled: '已取消' };
function formatTime(value: string) { return new Date(value).toLocaleString('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }); }
async function connect() { try { await store.connect(); if (store.connection.state === 'error') ElMessage.error(store.connection.error || '连接失败'); } catch (error) { ElMessage.error(error instanceof Error ? error.message : '连接失败'); } }
watch(() => store.connection.state, state => { if(state === 'connected') store.loadDrafts().catch(error => ElMessage.error(error instanceof Error ? error.message : '同步草稿失败')); }, { immediate: true });
</script>
<template>
  <div class="page-stack overview-page">
    <div class="page-heading"><div><span class="eyebrow">WORKSPACE OVERVIEW</span><h1>让每一次行动，都有条不紊。</h1><p class="muted">从信息发现到内容发布，在一个工作台中连接 XActions 的完整能力。</p></div><el-button :icon="Connection" :loading="store.connection.state === 'connecting'" :disabled="!store.desktopAvailable || store.connection.state === 'connected'" @click="connect">{{ store.connection.state === 'connected' ? '服务已连接' : '连接服务' }}</el-button></div>
    <div class="overview-metrics">
      <div class="metric surface"><span class="metric-icon indigo"><el-icon><Collection /></el-icon></span><div><span>可用工具</span><strong>{{ store.tools.length }}</strong></div><span class="metric-foot">{{ groups.length }} 个能力分类</span></div>
      <div class="metric surface"><span class="metric-icon blue"><el-icon><Search /></el-icon></span><div><span>无需发布审批</span><strong>{{ readCount }}</strong></div><span class="metric-foot">探索信息，理解数据</span></div>
      <div class="metric surface clickable" @click="router.push('/approvals')"><span class="metric-icon amber"><el-icon><Clock /></el-icon></span><div><span>等待审批</span><strong>{{ pending }}</strong></div><span class="metric-foot">{{ store.connection.state === 'connected' ? '确认内容后执行' : '连接后同步草稿' }}</span></div>
      <div class="metric surface"><span class="metric-icon green"><el-icon><CircleCheck /></el-icon></span><div><span>已记录执行</span><strong>{{ store.history.length }}</strong></div><span class="metric-foot">本地保存，可追溯导出</span></div>
    </div>
    <div class="overview-columns">
      <section class="surface quick-section"><div class="section-heading"><div><span class="eyebrow">QUICK START</span><h2>从这里开始</h2></div></div><div class="quick-grid">
        <button class="quick-card" @click="router.push({path:'/tools',query:{group:'read'}})"><span class="quick-icon blue"><el-icon><Search /></el-icon></span><strong>探索 X 上的信息</strong><p>搜索帖子、查看个人资料与对话。</p><span class="quick-action">打开读取工具 <el-icon><ArrowRight /></el-icon></span></button>
        <button class="quick-card" @click="router.push('/compose')"><span class="quick-icon indigo"><el-icon><EditPen /></el-icon></span><strong>写下一条新内容</strong><p>创作帖子、线程和投票，提交审批。</p><span class="quick-action">开始创作 <el-icon><ArrowRight /></el-icon></span></button>
        <button class="quick-card" @click="router.push({path:'/tools',query:{group:'analytics'}})"><span class="quick-icon green"><el-icon><DataAnalysis /></el-icon></span><strong>读懂账号表现</strong><p>调用分析能力，保留原始结果。</p><span class="quick-action">查看分析工具 <el-icon><ArrowRight /></el-icon></span></button>
      </div></section>
      <section class="surface session-card"><span class="eyebrow">LOCAL CONNECTION</span><div class="connection-art"><el-icon><Connection /></el-icon><span :class="['session-light',store.connection.state === 'connected' ? 'online' : '']"></span></div><h2>{{ store.connection.state === 'connected' ? '工作台已就绪' : '连接你的工作环境' }}</h2><p>{{ store.connection.state === 'connected' ? `已连接本机 XActions，发现 ${store.connection.toolCount} 个工具。` : '工具目录随时可浏览。连接本机服务后，即可执行工具并同步审批草稿。' }}</p><router-link to="/settings">管理连接与会话 <el-icon><ArrowRight /></el-icon></router-link></section>
    </div>
    <div class="overview-bottom">
      <section class="surface capability-section"><div class="section-heading"><div><span class="eyebrow">CAPABILITIES</span><h2>能力地图</h2></div><router-link to="/tools" class="text-link">全部工具 <el-icon><ArrowRight /></el-icon></router-link></div><div class="capability-grid"><button v-for="group in groups" :key="group.id" @click="router.push({path:'/tools',query:{group:group.id}})"><span class="group-dot" :style="{background:group.color}"></span><span>{{ group.label }}</span><b>{{ group.count }}</b><span class="group-bar" :style="{width: `${Math.max(8,group.count/store.tools.length*100)}%`,background:group.color}"></span></button></div></section>
      <section class="surface recent-section"><div class="section-heading"><div><span class="eyebrow">ACTIVITY</span><h2>最近执行</h2></div><router-link to="/history" class="text-link">查看全部</router-link></div><div v-if="!recent.length" class="activity-empty"><el-icon><Clock /></el-icon><h3>你的第一条记录，等待开始</h3><p>运行工具后，结果与参数会保存在这里。</p><el-button text type="primary" @click="router.push('/tools')">浏览工具库 <el-icon><ArrowRight /></el-icon></el-button></div><button v-for="run in recent" :key="run.id" class="recent-row" @click="router.push({path:'/history',query:{run:run.id}})"><span :class="['run-dot',run.status]"></span><span><strong>{{ toolTitle(run.toolName) }}</strong><small>{{ formatTime(run.createdAt) }}</small></span><el-tag size="small" :type="run.status === 'error' ? 'danger' : run.status === 'held' ? 'warning' : 'info'" effect="plain">{{ statusText[run.status] }}</el-tag></button></section>
    </div>
  </div>
</template>
<style scoped>
