{font-size:16px;margin:18px 0 6px}.session-card p{color:#8d97a7;font-size:12px;line-height:1.9;margin:0 0 22px}.session-card a,.text-link{display:inline-flex;align-items:center;gap:7px;color:#6366f1;text-decoration:none;font-size:11px}.session-card a{margin-top:auto}.overview-bottom{display:grid;grid-template-columns:1.2fr 1fr;gap:20px}.capability-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px 23px;margin-top:22px}.capability-grid button{position:relative;display:flex;align-items:center;gap:9px;border:0;background:#fff;padding:9px 0 11px;text-align:left;cursor:pointer;color:#637086;font-size:12px;overflow:hidden}.group-dot{width:6px;height:6px;border-radius:50%}.capability-grid b{margin-left:auto;font-size:11px;font-weight:500;color:#9ba4b3}.group-bar{position:absolute;bottom:0;height:2px;opacity:.28;left:15px;border-radius:2px}.recent-row{display:flex;align-items:center;gap:12px;width:100%;padding:16px 0;border:0;border-bottom:1px solid #f0f3f8;background:#fff;text-align:left;cursor:pointer}.recent-row strong{display:block;font-size:12px;font-weight:550;color:#526177}.recent-row small{display:block;font-size:10px;color:#a0a9b7;margin-top:5px}.recent-row .el-tag{margin-left:auto}.run-dot{width:7px;height:7px;border-radius:50%;background:#94a3b8}.run-dot.success{background:#34b39b}.run-dot.held{background:#d5a453}.run-dot.error{background:#e97b7b}.activity-empty{text-align:center;padding:47px 8px 25px;color:#a7b0be}.activity-empty>.el-icon{font-size:28px}.activity-empty h3{font-size:13px;font-weight:500;color:#758196;margin:15px 0 8px}.activity-empty p{font-size:11px}@media(max-width:1150px){.overview-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.overview-columns,.overview-bottom{grid-template-columns:1fr}.session-card{display:none}}@media(max-width:760px){.quick-grid{grid-template-columns:1fr}.quick-card p{min-height:0}.quick-action{margin-top:12px}}
</style>
